// === CONTRATO DE ENTRADA (lo que manda el Manager) ===
// { requestId, intencion:'REDACCION_EMAIL', destinatario, vacantes:[...], tono }
try {
  const inp = $input.first().json || {};
  const requestId = inp.requestId || ('REQ-' + Date.now());
  const destinatario = inp.destinatario || 'destinatario@ejemplo.com';
  const tono = inp.tono || 'profesional';
  const vacantes = Array.isArray(inp.vacantes) ? inp.vacantes : [];

  if (!vacantes.length) {
    // === MANEJO DE FALLOS: sin insumos no puedo redactar ===
    return [{ json: {
      status: 'error',
      worker: 'worker2_redaccion_email',
      requestId,
      data: null,
      error: { code: 'SIN_VACANTES', message: 'No llegaron vacantes para redactar el correo.' }
    }}];
  }

  const saludo = tono === 'formal' ? 'Estimado equipo de reclutamiento:' : 'Hola equipo:';
  let lista = '';
  for (const v of vacantes) {
    lista += '<li><a href="' + (v.url || '#') + '" style="color:#7c5cff">' + (v.titulo || 'Vacante') + '</a> &mdash; ' + (v.empresa || '') + '</li>';
  }
  const asunto = 'Postulacion a ' + vacantes.length + ' vacante(s) remota(s)';
  const cuerpo_html = '<div style="font-family:Arial;max-width:600px">' +
    '<p>' + saludo + '</p>' +
    '<p>Mi nombre es Lleyton Murphy y quiero postularme a las siguientes posiciones remotas que encajan con mi perfil en IA Automation y Data:</p>' +
    '<ul>' + lista + '</ul>' +
    '<p>Adjunto mi perfil y quedo a disposicion para una entrevista. Muchas gracias.</p>' +
    '<p>Saludos,<br>Lleyton Murphy</p></div>';

  return [{ json: {
    status: 'success',
    worker: 'worker2_redaccion_email',
    requestId,
    data: { destinatario, asunto, cuerpo_html },
    error: null
  }}];
} catch (e) {
  return [{ json: {
    status: 'error',
    worker: 'worker2_redaccion_email',
    requestId: 'REQ-desconocido',
    data: null,
    error: { code: 'EXCEPCION', message: String(e && e.message || e) }
  }}];
}
